    physicalExam: { 'Physical Strength': 'Standard', Mobility: 'Excellent', Endurance: 'Normal', 'Tactical Acumen': 'Normal', 'Combat Skill': 'Standard', 'Originium Arts': 'Standard' },
    talents: [{ name: 'Lightweight', desc: 'DP Cost -1', elite: 'E1' }],
